using System.Runtime.InteropServices;

namespace Beutl.Graphics.Shaders;

/// <summary>The four 32-bit words consumed by DrawIndirect. Values may be generated by a compute pass.</summary>
[StructLayout(LayoutKind.Sequential)]
public readonly record struct DrawCommand(uint VertexCount, uint InstanceCount = 1, uint FirstVertex = 0, uint FirstInstance = 0);

/// <summary>The five 32-bit words consumed by DrawIndexedIndirect.</summary>
[StructLayout(LayoutKind.Sequential)]
public readonly record struct IndexedDrawCommand(uint IndexCount, uint InstanceCount = 1, uint FirstIndex = 0,
    int VertexOffset = 0, uint FirstInstance = 0);

/// <summary>The three workgroup counts consumed by DispatchIndirect.</summary>
[StructLayout(LayoutKind.Sequential)]
public readonly record struct DispatchCommand(uint X, uint Y = 1, uint Z = 1);

internal sealed record ShaderIndirectCommand(ShaderBuffer Buffer, long Offset, int Count, int Stride, int CommandSize)
{
    public void Validate()
    {
        if (Offset < 0 || Offset % 4 != 0 || Count < 0 || Count > 1 && (Stride < CommandSize || Stride % 4 != 0)
            || Offset > Buffer.ByteLength || Count > 0 && checked(Offset + (long)(Count - 1) * Stride + CommandSize) > Buffer.ByteLength)
            throw new ArgumentException($"Indirect command range or alignment is invalid for buffer '{Buffer.Name}'.");
    }
}
